<script setup lang="ts">
import{computed,onMounted,ref}from'vue'
import{useRoute,useRouter}from'vue-router'
import{ElMessage,ElMessageBox}from'element-plus'
import{v12ResourceApi}from'@/api/v12Resource'
import{useAuthStore}from'@/stores/auth'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),data=ref<any>({}),loading=ref(false),ipHistory=ref<any[]>([]),operations=ref<any[]>([])
const type=computed(()=>String(route.meta.resourceType||'CENTOS')),id=computed(()=>Number(route.params.id))
async function load(){loading.value=true;try{if(type.value==='CENTOS')data.value=(await v12ResourceApi.centosDetail(id.value)).data.data;else if(type.value==='ROS')data.value=(await v12ResourceApi.rosDetail(id.value)).data.data;else{data.value=(await v12ResourceApi.lineDetail(id.value)).data.data;const [h,o]=await Promise.all([v12ResourceApi.lineIpHistory(id.value),v12ResourceApi.lineOperations(id.value)]);ipHistory.value=h.data.data;operations.value=o.data.data}}finally{loading.value=false}}
async function autoSwitch(){const enabled=!Boolean(data.value.auto_switch);const {value}=await ElMessageBox.prompt(`确认${enabled?'开启':'关闭'}自动切换，请填写原因`,'ROS自动切换',{inputValidator:v=>!!String(v||'').trim()||'必须填写原因'});await v12ResourceApi.setRosAutoSwitch(id.value,enabled,String(value));ElMessage.success('配置已更新');load()}
async function ha(){const {value}=await ElMessageBox.prompt('请输入主备角色：PRIMARY / BACKUP / STANDALONE','设置ROS主备',{inputPattern:/^(PRIMARY|BACKUP|STANDALONE)$/i,inputErrorMessage:'请输入PRIMARY/BACKUP/STANDALONE'});const {value:reason}=await ElMessageBox.prompt('请输入操作原因','设置ROS主备');await v12ResourceApi.setRosHa(id.value,{role:String(value).toUpperCase(),replacementRosId:data.value.replacement_ros_id||null,switchStatus:data.value.switch_status||'NORMAL',reason:String(reason)});ElMessage.success('主备配置已更新');load()}
async function setLineType(){const current=data.value.line_type||'';const {value}=await ElMessageBox.prompt('请输入线路类型：SHARED（共享）或 LONG（长效）','设置线路类型',{inputValue:current,inputPattern:/^(SHARED|LONG)$/i,inputErrorMessage:'仅支持 SHARED 或 LONG'});const {value:reason}=await ElMessageBox.prompt('请输入修改原因','设置线路类型',{inputValidator:v=>!!String(v||'').trim()||'必须填写原因'});await v12ResourceApi.setLineType(id.value,String(value).toUpperCase() as 'SHARED'|'LONG',String(reason));ElMessage.success('线路类型已更新');load()}
function fmt(v:any){return v===null||v===undefined||v===''?'—':String(v)}
function lineTypeLabel(v:any){return v==='SHARED'?'共享':v==='LONG'?'长效':'未设置'}
onMounted(load)
</script>
<template><div class="page-stack" v-loading="loading"><div class="page-head"><div><el-button link @click="router.back()">← 返回列表</el-button><h1>{{type==='CENTOS'?'CentOS详情':type==='ROS'?'ROS详情':'家宽/线路详情'}}</h1><p>{{data.resource_code||data.resource_name}}</p></div><div v-if="type==='ROS'" class="actions"><el-button v-if="auth.hasPermission('resource:ros:operate')" @click="ha">设置主备</el-button><el-button v-if="auth.hasPermission('resource:ros:operate')" type="primary" @click="autoSwitch">{{data.auto_switch?'关闭':'开启'}}自动切换</el-button></div><div v-else-if="type==='LINE'" class="actions"><el-button v-if="auth.hasPermission('resource:line:operate')" type="primary" @click="setLineType">设置线路类型</el-button></div></div>
<template v-if="type==='CENTOS'"><el-card shadow="never"><template #header><b>基础与运行信息</b></template><el-descriptions :column="4" border><el-descriptions-item label="主机ID">{{fmt(data.resource_code)}}</el-descriptions-item><el-descriptions-item label="主机名称">{{fmt(data.resource_name)}}</el-descriptions-item><el-descriptions-item label="账号">{{fmt(data.host_account)}}</el-descriptions-item><el-descriptions-item label="管理IP">{{fmt(data.management_ip_text)}}</el-descriptions-item><el-descriptions-item label="地点">{{fmt(data.location_name)}}</el-descriptions-item><el-descriptions-item label="运营商">{{fmt(data.carrier_code)}}</el-descriptions-item><el-descriptions-item label="CPU">{{fmt(data.cpu_usage)}}%</el-descriptions-item><el-descriptions-item label="内存">{{fmt(data.memory_usage)}}%</el-descriptions-item><el-descriptions-item label="系统负载">{{fmt(data.system_load)}}</el-descriptions-item><el-descriptions-item label="硬盘">{{fmt(data.disk_usage)}}%</el-descriptions-item><el-descriptions-item label="ROS数量">{{fmt(data.ros_count)}}</el-descriptions-item><el-descriptions-item label="线路数量">{{fmt(data.line_count)}}</el-descriptions-item><el-descriptions-item label="VPN支持">{{data.vpn_supported?'支持':'否'}}</el-descriptions-item><el-descriptions-item label="PPPoE服务器">{{fmt(data.pppoe_server_name)}}</el-descriptions-item><el-descriptions-item label="心跳时间">{{fmt(data.last_communicated_at)}}</el-descriptions-item><el-descriptions-item label="状态">{{fmt(data.online_status)}}</el-descriptions-item></el-descriptions></el-card><el-card shadow="never"><template #header><b>下属ROS</b></template><el-table :data="data.rosList||[]" border stripe><el-table-column prop="resource_code" label="ROS ID"/><el-table-column prop="resource_name" label="名称"/><el-table-column prop="online_status" label="状态"/><el-table-column prop="line_total" label="线路数"/><el-table-column prop="line_online" label="在线线路"/><el-table-column prop="current_ip_count" label="当前IP"/><el-table-column prop="b_prefix_count" label="B段"/><el-table-column prop="c_prefix_count" label="C段"/><el-table-column prop="bas_count" label="BAS"/><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="router.push(`/resources/ros/${s.row.id}`)">详情</el-button></template></el-table-column></el-table></el-card></template>
<template v-else-if="type==='ROS'"><el-card shadow="never"><template #header><b>ROS运行信息</b></template><el-descriptions :column="4" border><el-descriptions-item label="ROS ID">{{fmt(data.resource_code)}}</el-descriptions-item><el-descriptions-item label="记录名">{{fmt(data.record_name)}}</el-descriptions-item><el-descriptions-item label="所属CentOS">{{fmt(data.centos_code)}}</el-descriptions-item><el-descriptions-item label="状态">{{fmt(data.online_status)}}</el-descriptions-item><el-descriptions-item label="CPU">{{fmt(data.cpu_usage)}}%</el-descriptions-item><el-descriptions-item label="内存">{{fmt(data.memory_usage)}}%</el-descriptions-item><el-descriptions-item label="系统负载">{{fmt(data.system_load)}}</el-descriptions-item><el-descriptions-item label="硬盘">{{fmt(data.disk_usage)}}%</el-descriptions-item><el-descriptions-item label="线路总数">{{fmt(data.line_total)}}</el-descriptions-item><el-descriptions-item label="在线线路">{{fmt(data.line_online)}}</el-descriptions-item><el-descriptions-item label="当前拨号IP">{{fmt(data.current_ip_count)}}</el-descriptions-item><el-descriptions-item label="B/C段">{{fmt(data.b_prefix_count)}} / {{fmt(data.c_prefix_count)}}</el-descriptions-item><el-descriptions-item label="BAS数量">{{fmt(data.bas_count)}}</el-descriptions-item><el-descriptions-item label="开机时长(秒)">{{fmt(data.uptime_seconds)}}</el-descriptions-item><el-descriptions-item label="主备类型">{{fmt(data.ha_role)}}</el-descriptions-item><el-descriptions-item label="替换ROS">{{fmt(data.replacement_ros_code)}}</el-descriptions-item><el-descriptions-item label="切换状态">{{fmt(data.switch_status)}}</el-descriptions-item><el-descriptions-item label="自动切换">{{data.auto_switch?'开启':'关闭'}}</el-descriptions-item><el-descriptions-item label="最近上报">{{fmt(data.last_report_at)}}</el-descriptions-item></el-descriptions></el-card><el-card shadow="never"><template #header><div class="card-head"><b>BAS/BRAS汇总</b><el-button link type="primary" @click="router.push({path:'/resources/lines',query:{rosId:id}})">查看全部线路</el-button></div></template><el-table :data="data.basStatistics||[]" border stripe><el-table-column prop="bas_name" label="BAS/BRAS"/><el-table-column prop="bas_address" label="地址"/><el-table-column prop="line_total" label="线路数"/><el-table-column prop="online_lines" label="在线线路"/><el-table-column prop="current_ip_count" label="当前IP数"/></el-table></el-card></template>
<template v-else><el-card shadow="never"><template #header><div class="card-head"><b>线路基础信息</b><el-tag :type="data.line_type==='LONG'?'warning':'info'">{{lineTypeLabel(data.line_type)}}</el-tag></div></template><el-descriptions :column="4" border><el-descriptions-item label="线路ID">{{fmt(data.resource_code)}}</el-descriptions-item><el-descriptions-item label="线路别名">{{fmt(data.line_alias)}}</el-descriptions-item><el-descriptions-item label="所属ROS">{{fmt(data.ros_code)}}</el-descriptions-item><el-descriptions-item label="所属CentOS">{{fmt(data.centos_code)}}</el-descriptions-item><el-descriptions-item label="拨号账号">{{fmt(data.broadband_account)}}</el-descriptions-item><el-descriptions-item label="账号前缀">{{fmt(data.account_prefix)}}</el-descriptions-item><el-descriptions-item label="当前IP">{{fmt(data.current_public_ip_text)}}</el-descriptions-item><el-descriptions-item label="HTTP/SOCKS5">{{fmt(data.http_port)}} / {{fmt(data.socks5_port)}}</el-descriptions-item><el-descriptions-item label="域名">{{fmt(data.domain_name)}}</el-descriptions-item><el-descriptions-item label="客户">{{fmt(data.customer_name)}}</el-descriptions-item><el-descriptions-item label="线路类型">{{lineTypeLabel(data.line_type)}}</el-descriptions-item><el-descriptions-item label="状态">{{fmt(data.online_status)}} / {{fmt(data.dial_status)}}</el-descriptions-item><el-descriptions-item label="限制人数/在用">{{fmt(data.user_limit)}} / {{fmt(data.active_users)}}</el-descriptions-item><el-descriptions-item label="重拨/重启间隔">{{fmt(data.restart_interval_minutes)}} 分钟</el-descriptions-item><el-descriptions-item label="VPN支持">{{data.vpn_supported?'支持':'否'}}</el-descriptions-item><el-descriptions-item label="VPN重拨监控">{{data.vpn_redial_monitor?'启用':'关闭'}}</el-descriptions-item><el-descriptions-item label="BAS/BRAS">{{fmt(data.bas_name)}}</el-descriptions-item><el-descriptions-item label="BAS地址">{{fmt(data.bas_address)}}</el-descriptions-item><el-descriptions-item label="省/市">{{fmt(data.province_code)}} / {{fmt(data.city_code)}}</el-descriptions-item><el-descriptions-item label="运营商">{{fmt(data.carrier_code)}}</el-descriptions-item><el-descriptions-item label="平均延迟">{{fmt(data.latency_ms)}} ms</el-descriptions-item><el-descriptions-item label="资源池">{{fmt(data.pool_names)}}</el-descriptions-item><el-descriptions-item label="最近拨号">{{fmt(data.last_dial_at)}}</el-descriptions-item><el-descriptions-item label="ROS上报">{{fmt(data.last_ros_report_at)}}</el-descriptions-item></el-descriptions><el-alert class="mt" type="info" :closable="false" title="资源池中的线路类型只有共享和长效；独享IP、VPN、隧道在各自产品/业务模块维护，不通过线路类型进入资源池。"/></el-card><el-card shadow="never"><el-tabs><el-tab-pane label="IP变化历史"><el-table :data="ipHistory" border stripe><el-table-column prop="ip_address" label="IP"/><el-table-column prop="change_type" label="变化类型"/><el-table-column prop="first_seen_at" label="首次出现"/><el-table-column prop="last_seen_at" label="最后出现"/></el-table></el-tab-pane><el-tab-pane label="运维操作日志"><el-table :data="operations" border stripe><el-table-column prop="operation_type" label="操作"/><el-table-column prop="operation_source" label="来源"/><el-table-column prop="result_status" label="结果"/><el-table-column prop="result_message" label="说明"/><el-table-column prop="created_at" label="时间"/></el-table></el-tab-pane></el-tabs></el-card></template></div></template>
<style scoped>.page-stack{display:grid;gap:16px}.page-head,.card-head,.actions{display:flex;justify-content:space-between;gap:10px}.page-head h1{margin:8px 0 4px}.page-head p{margin:0;color:#7b8495}.card-head{width:100%;align-items:center}.mt{margin-top:14px}</style>
